/** Optimistically updates an offering aggregate without accepting a client counter. */
public record UpdateOfferingCommand(String offeringId,String termId,String courseId,String teacherUserId,String className,int capacity,String offeringStatus,long expectedVersion,List<CreateOfferingCommand.ScheduleInput> schedules) implements Serializable { @Serial private static final long serialVersionUID=1L; public UpdateOfferingCommand{Objects.requireNonNull(offeringId);new CreateOfferingCommand(termId,courseId,teacherUserId,className,capacity,offeringStatus,schedules);schedules=List.copyOf(schedules);CourseValidation.text("offeringId",offeringId,36);if(expectedVersion<0)throw new IllegalArgumentException("invalid offering");} }
